entries[62673] = { ["name"] = "Köder mit Federn", ["text"] = "Benötigt Angeln (100)\nBenutzen: Bei Anwendung auf Eure Angelrute wird die Fähigkeit 'Angeln' 10 Minuten lang um 100 Punkte erhöht.\nVerkaufspreis:" }
entries[62674] = { ["name"] = "Hochlandschnaps", ["text"] = "Benutzen: Ein starkes alkoholisches Getränk.\nVerkaufspreis:" }
entries[62675] = { ["name"] = "Sternenfeuerespresso", ["text"] = "Benötigt Stufe 80\nBenutzen: Stellt im Verlauf von 30 Sek. insgesamt 96000 Mana wieder her und macht ein wenig nüchterner. Ihr müsst beim Trinken sitzen bleiben.\nVerkaufspreis:" }
entries[62676] = { ["name"] = "Schwarzgebratene Überraschung", ["text"] = "Benötigt Stufe 80\nBenutzen: Stellt im Verlauf von 30 Sek. insgesamt 67500 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\nVerkaufspreis:" }
