entries[62678] = { ["name"] = "Knuspersnack: \"Spegg\"", ["text"] = "Benötigt Stufe 75\nBenutzen: Erhöht die Stärke Eures Begleiters um 75. Hält 1 Stunde lang an.\nVerkaufspreis:" }
entries[62679] = { ["name"] = "Angereicherter Fischkeks", ["text"] = "Benötigt Stufe 75\nBenutzen: Erhöht die Ausdauer Eures Begleiters um 110. Hält 1 Stunde lang an.\nVerkaufspreis:" }
entries[62680] = { ["name"] = "Schokoladenkeks", ["text"] = "Benutzen: Bessert Eure Laune ein wenig auf.\nVerkaufspreis:" }
entries[62705] = { ["name"] = "Linse der Sonne", ["text"] = "Questgegenstand\n\"Fühlt sich seltsam kühl an.\"" }
entries[62714] = { ["name"] = "Dämmerfangs Balg", ["text"] = "Questgegenstand\n\"Ein passendes Leichentuch für Helgrum.\"" }
