entries[62799] = { ["name"] = "Rezept: Gebratenes Drachenfestmahl", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (500)\nBenutzen: Lehrt Euch, wie man ein gebratenes Drachenfestmahl zubereitet.\nVerkaufspreis:\nGebratenes Drachenfestmahl\nWird beim Aufheben gebunden\nBenötigt Stufe 80\nBenutzen: Richtet für Eure Gruppe oder Euren Schlachtzug ein Drachenfestmahl her! Stellt im Verlauf von 30 Sek. 67500 Gesundheit und 45000 Mana wieder her. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 60 Ausdauer und ein für Euch nützlicher Wert wird um 60 erhöht.\nVerkaufspreis:\nBenötigt Drachenflanke (3), Zarter Flügel (2)" }
entries[62800] = { ["name"] = "Rezept: Meeresfrüchtefestmahl Magnifique", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (525)\nBenutzen: Lehrt Euch, wie man ein Meeresfrüchtefestmahl Magnifique zubereitet.\nVerkaufspreis:\nMeeresfrüchtefestmahl Magnifique\nWird beim Aufheben gebunden\nBenötigt Stufe 80\nBenutzen: Richtet für Eure Gruppe oder Euren Schlachtzug ein Meeresfrüchtefestmahl Magnifique her! Stellt im Verlauf von 30 Sek. 96000 Gesundheit und 96000 Mana wieder her. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 90 Ausdauer und ein für Euch nützlicher Wert wird um 90 erhöht.\nVerkaufspreis:\nBenötigt Hochlandguppy (2), Lavaschuppenwels (2), Klafteraal (2)" }
