entries[63359] = { ["name"] = "Banner der Zusammenarbeit", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Gilde\n- Freundlich\nBenutzen: Stellt eine Schlachtstandarte Eurer Gilde auf, die den Erfahrungs-, Ehren- und Rufgewinn aller Gildenmitglieder für das Töten von Monstern im Umkreis von 100 Metern um die Standarte um 5% erhöht. Hält 15 Min. lang an. (10 Min Abklingzeit)\nVerkaufspreis:" }
entries[63374] = { ["name"] = "Bahrums Hose", ["text"] = "Questgegenstand\nEinzigartig\n\"Graviert: Bahrum.\"" }
entries[63376] = { ["name"] = "Schlachtstandarte von Höllschreis Hand", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Höllschreis Hand\n- Respektvoll\nBenutzen: Stellt eine Schlachtstandarte von Höllschreis Hand auf, die über 40000 Gesundheit verfügt und den verursachten Schaden aller Gruppenmitglieder im Umkreis von 45 Metern um die Standarte um 10% erhöht. Hält 2 Min. lang an und kann nur auf Tol Barad aufgestellt werden. (10 Min Abklingzeit)" }
entries[63377] = { ["name"] = "Schlachtstandarte der Wächter von Baradin", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Wächter von Baradin\n- Respektvoll\nBenutzen: Stellt eine Schlachtstandarte der Wächter von Baradin auf, die über 40000 Gesundheit verfügt und den verursachten Schaden aller Gruppenmitglieder im Umkreis von 45 Metern um die Standarte um 10% erhöht. Hält 2 Min. lang an und kann nur auf Tol Barad aufgestellt werden. (10 Min Abklingzeit)" }
entries[63378] = { ["name"] = "Wappenrock von Höllschreis Hand", ["text"] = "Wird beim Aufheben gebunden\nWappenrock\nBenötigt Höllschreis Hand\n- Wohlwollend\nBenutzen: Teleportiert den Zaubernden zu Höllschreis Griff auf Tol Barad. (4 Std. Abklingzeit)\nVerkaufspreis:" }
entries[63379] = { ["name"] = "Wappenrock der Wächter von Baradin", ["text"] = "Wird beim Aufheben gebunden\nWappenrock\nBenötigt Wächter von Baradin\n- Wohlwollend\nBenutzen: Teleportiert den Zaubernden zum Baradinbasislager auf Tol Barad. (4 Std. Abklingzeit)" }
entries[63383] = { ["name"] = "Sündschwelgers Augenbinde", ["text"] = "Questgegenstand\nBenutzen: Tragt die Augenbinde, die es Euch ermöglicht, die wahre Gestalt von verwandelten Dämonen zu sehen. Ihr müsst Euch in der Jadefeuerschlucht befinden, um sie nutzen zu können. (30 Sek. Abklingzeit)" }
entries[63384] = { ["name"] = "Mechanischer Anzug ZX-5103", ["text"] = "Benötigt Stufe 80\nBenötigt Ingenieurskunst (450)\nBenutzen: Beschwört einen mechanischen Anzug, Modell ZX-5103, inklusive Bewaffnung. Der Anzug kann 5 Min. lang genutzt werden, bevor er wieder aufgeladen und repariert werden muss. (5 Min Abklingzeit)\n3 Aufladungen\nVerkaufspreis:" }
entries[63387] = { ["name"] = "Wasser des Wisperwindmondbrunnens", ["text"] = "Questgegenstand\nBenutzen: Gießt das Mondbrunnenwasser in der Mitte der Hügels in der Mitte des Eisenwaldes aus." }
entries[63388] = { ["name"] = "Löschstaub", ["text"] = "\"Dieser feine Staub wird von Inschriftenhändlern verkauft und von Schreibern hergestellt. Er ist nötig, um mächtige Glyphen zu entfernen, damit neue eingefügt werden können. Â Nur mit Stufe 81 oder höher zu verwenden.\"\nVerkaufspreis:" }
entries[63390] = { ["name"] = "Disziplinarknüppel des Schwarzfels", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Diszipliniert einen Schwarzfelsorc, einen Oger der Feuermägen, einen Troll der Gluthauer oder einen Goblinsöldner in den Feldern der Ehre." }
entries[63391] = { ["name"] = "Bandage der Wächter von Baradin", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Erste Hilfe (500)\nBenötigt Wächter von Baradin\n- Freundlich\nBenutzen: Heilt im Verlauf von 8 Sek. 35000 Schaden. Funktioniert nur auf Tol Barad." }
entries[63392] = { ["name"] = "Tol'virzelt", ["text"] = "Questgegenstand" }
entries[63393] = { ["name"] = "Tragbare Drachenfaust", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Feuert einen flammenden Speer auf einen Schwarzdrache des Drachenmals. (5 Sek. Abklingzeit)" }
entries[63395] = { ["name"] = "Delaris' Prisma", ["text"] = "Questgegenstand\nBenutzen: Beschwört ein Abbild dessen, was Wichtel am meisten fürchten. (3 Sek. Abklingzeit)\n\"So wunderschön bunt!\"" }
entries[63396] = { ["name"] = "Ganz großer Knaller", ["text"] = "Benötigt Ingenieurskunst (440)\nBenötigt Gobliningenieur\nBenutzen: Verursacht 5006 Feuerschaden und macht Ziele in einem Umkreis von 8 Metern 5 Sek. lang handlungsunfähig. Jeglicher Schaden wird den Effekt beenden. Funktioniert noch besser gegen nichtsahnende Ziele. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[63398] = { ["name"] = "Gürteltierjunges", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euer Gürteltierjunges beschwören oder wieder freigeben.\nVerkaufspreis:" }
